from pathlib import Path
import json
r=Path(__file__).resolve().parent
p=r/"site/duplicates.js"
s=p.read_text()
edits=json.loads('[["const email=v=>String(v||\'\').trim().toLowerCase();", "const email=v=>String(v||\'\').trim().toLowerCase();\\nconst NICKNAMES=[[\'william\',\'bill\',\'billy\',\'will\'],[\'robert\',\'bob\',\'bobby\',\'rob\'],[\'richard\',\'rick\',\'ricky\',\'dick\'],[\'elizabeth\',\'liz\',\'beth\',\'betty\',\'lizzie\'],[\'james\',\'jim\',\'jimmy\'],[\'joseph\',\'joe\',\'joey\'],[\'margaret\',\'maggie\',\'peggy\'],[\'patricia\',\'pat\',\'patty\'],[\'katherine\',\'catherine\',\'kathy\',\'cathy\',\'kate\'],[\'edward\',\'ed\',\'eddie\',\'ted\'],[\'michael\',\'mike\'],[\'thomas\',\'tom\',\'tommy\'],[\'anthony\',\'tony\'],[\'charles\',\'charlie\',\'chuck\'],[\'dorothy\',\'dot\',\'dottie\'],[\'susan\',\'sue\',\'susie\']];\\nfunction near(a,b){if(a===b)return true;if(/[0-9]/.test(a+b)||Math.abs(a.length-b.length)>1||Math.min(a.length,b.length)<3)return false;const d=Array.from({length:a.length+1},(_,i)=>i);for(let j=1;j<=b.length;j++){let prev=d[0];d[0]=j;for(let i=1;i<=a.length;i++){const before=d[i];d[i]=Math.min(d[i]+1,d[i-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=before;}}return d[a.length]<=1;}\\nfunction similarFirst(a,b){return a===b||NICKNAMES.some(g=>g.includes(a)&&g.includes(b))||near(a,b);}"], [" const related=al===bl&&af.split(\' \')[0]===bf.split(\' \')[0];\\n if(!exact&&!swapped&&!(contact&&related))return null;\\n return {strong:exact&&!!contact,reasons:[exact||swapped?\'Matching resident name\':\'Similar resident name\',...(contact?[\'Matching contact details\']:[])]};", " const firstA=af.split(\' \')[0],firstB=bf.split(\' \')[0];\\n const related=al===bl&&(similarFirst(firstA,firstB)||contact&&firstA[0]===firstB[0])||firstA===firstB&&Math.min(al.length,bl.length)>=4&&near(al,bl);\\n if(!exact&&!swapped&&!related)return null;\\n return {strong:exact&&!!contact,reasons:[exact||swapped?\'Matching resident name\':\'Similar resident name \\u2014 possible spelling variation\',...(contact?[\'Matching contact details\']:[])]};"]]')
for old,new in edits:
 if s.count(old)!=1:raise SystemExit("Unexpected duplicate name matcher source")
 s=s.replace(old,new)
p.write_text(s)
p=r/"test/morgan-duplicates.test.mjs"
p.write_text(p.read_text()+"\ntest('spelling differences and familiar first-name variants are flagged but never automatically merged',()=>{const base={id:'a',first:'William',last:'Johnson',caller:{}};for(const first of ['Bill','Wiliam']){const peer={...base,id:'b',first};assert.ok(D.match(base,peer));assert.equal(D.match(base,peer).strong,false);}assert.ok(D.match({...base,first:'Maria',last:'Gonzalez'},{...base,id:'b',first:'Maria',last:'Gonzales'}));assert.equal(D.match({...base,first:'Amanda'},{...base,id:'b',first:'Joseph'}),null);});\n")
